#!/bin/bash
# harness-ignores.sh - shared .gitignore helpers (sourced by harness-setup.sh and harness-step.sh).
# Not meant to be executed directly. Messages go to stderr so KEY=VALUE output stays clean.

# Files inside .harness/ that must never be committed: runner state, and the wrappers, which
# contain machine-specific plugin paths and are regenerated by setup / harness-run.
HARNESS_WRAPPERS=(feature-list.sh step.sh run.sh status.sh backlog.sh doctor.sh notify.sh trigger.sh intake.sh replay.sh report.sh coverage.sh)
HARNESS_IGNORES=("sessions/" "STOP" "runner.pid" "session_count" "last-run.md" ".step_state.json" ".trusted" ".lock" ".lock_snapshot.json" ".proposals_snapshot.json" "ledger.jsonl" "events.jsonl" "triggers/" "worktrees/" "evidence/" "coverage/*" "!coverage/baseline.json" "*.tmp.*" "${HARNESS_WRAPPERS[@]}")
PROJECT_IGNORES=(".playwright-mcp/" "node_modules/" "__pycache__/" "*.pyc" ".DS_Store" ".env" ".env.*" ".coverage" "htmlcov/" "*.pem" "*.key")

add_ignores() { # file, entries...  (merge, never overwrite)
  local f="$1" e added=0; shift
  touch "$f"
  for e in "$@"; do
    if ! grep -qxF -- "$e" "$f"; then echo "$e" >> "$f"; added=$((added + 1)); fi
  done
  if [[ $added -gt 0 ]]; then echo "  $f: added $added ignore entries" >&2; fi
  return 0
}

# Ignore sets chosen from what the project contains (call again once source files exist).
add_language_ignores() {
  local -a e=()
  [[ -f package.json ]] && e+=("dist/" "build/" "coverage/" ".next/" ".nuxt/" ".turbo/" ".cache/" "npm-debug.log*" "yarn-error.log*")
  if [[ -f pyproject.toml || -f requirements.txt || -f setup.py || -f Pipfile ]] || ls ./*.py >/dev/null 2>&1; then
    e+=(".venv/" "venv/" ".pytest_cache/" ".mypy_cache/" ".ruff_cache/" "*.egg-info/" "dist/" "build/")
  fi
  [[ -f Cargo.toml ]] && e+=("target/")
  [[ -f go.mod ]] && e+=("bin/")
  [[ -f pom.xml || -f build.gradle || -f build.gradle.kts ]] && e+=("target/" "build/" ".gradle/")
  [[ -f Gemfile ]] && e+=("vendor/bundle/" ".bundle/")
  if [[ ${#e[@]} -gt 0 ]]; then add_ignores .gitignore "${e[@]}"; fi
  return 0
}

# Stop tracking wrappers that an older version committed (machine-specific paths).
untrack_wrappers() { # harness dir
  local w
  for w in "${HARNESS_WRAPPERS[@]}"; do
    if git ls-files --error-unmatch "$1/$w" >/dev/null 2>&1; then
      git rm -q --cached "$1/$w" >/dev/null 2>&1 && echo "  untracked $1/$w (machine-specific wrapper)" >&2
    fi
  done
  return 0
}

# Everything the harness wants ignored; safe and cheap to run at every loop start.
ensure_all_ignores() { # harness dir
  add_ignores "$1/.gitignore" "${HARNESS_IGNORES[@]}"
  add_ignores .gitignore "${PROJECT_IGNORES[@]}"
  add_language_ignores
  untrack_wrappers "$1"
}
